import { Modal } from "antd";
import React, { useEffect, useState } from "react";
import { ToastContainer } from "react-toastify";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomSwitch,
  CustomTimePicker,
} from "../../../components";
import useApi from "../../../hooks/useApi";
import transportApi from "../../../api/transport/transportApi";
import { useFormik } from "formik";
import * as Yup from "yup";
import dayjs from "dayjs";
import { Button } from "@heroui/react";
import countiesApi from "../../../api/countiesApi";

function PickupPointsFormModal({
  ismodalOpen,
  setisModalOpen,
  transfer_point,
  modalTitle = "Add new transfer point",
  updated,
  setUpdated,
}) {
  const [routes, setRoutes] = useState([]);

  const transportActionsApi = useApi(transportApi.transportAction);
  const getRoutesActionsApi = useApi(transportApi.transportAction);

  const [towns, setTowns] = useState([]);
  const getTownsApi = useApi(countiesApi.countiesAction);
  const getTowns = async () => {
    await getTownsApi.request({
      action: "GetAllTowns",
    });
  };

  useEffect(() => {
    if (getTownsApi.data && getTownsApi.data.length) {
      setTowns(
        getTownsApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }

    console.log("getVehiclesActionsApi.data", getTownsApi.data);
  }, [getTownsApi.data]);

  useEffect(() => {
    getTowns();
  }, []);

  useEffect(() => {
    if (getRoutesActionsApi.data && getRoutesActionsApi.data.length) {
      setRoutes(
        getRoutesActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }

    console.log("getRoutesActionsApi.data", getRoutesActionsApi.data);
  }, [getRoutesActionsApi.data]);

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  const handleTripAction = async (data) => {
    console.log("data at", data);
    const result = await transportActionsApi.request(data);

    if (result.ok) {
      console.log("res", result);
      setUpdated(true);
    }
  };

  const handleDepartureDateChange = (date, dateString) => {
    formik.setFieldValue("departure_date", dateString);
  };

  const handleDepartureTimeChange = (timeArray, time) => {
    console.log("Dep", time);
    formik.setFieldValue("departure_time", time);
  };
  const formik = useFormik({
    initialValues: {
      town: transfer_point
        ? { label: transfer_point.city_title, value: transfer_point.city }
        : "",

      title: transfer_point ? transfer_point.title : "",
    },

    validationSchema: Yup.object({
      town: Yup.object().required("Town is required"),
      title: Yup.string().required("Title is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);

      if (transfer_point) {
        handleTripAction({
          action: "UpdateTransferPoint",
          transfer_point_details: {
            transfer_point_id: transfer_point.id,
            town: values.town.value,
            title: values.title,
            abbreviation: values.abbreviation,
            is_active: values.is_active,
          },
        });
      } else {
        handleTripAction({
          action: "CreateTransferPoint",
          transfer_point_details: {
            town: values.town.value,
            title: values.title,
            abbreviation: values.abbreviation,
            is_active: values.is_active,
          },
        });
      }
      setisModalOpen(false);

      resetForm();
    },
  });

  const [switchStatus, setswitchStatus] = useState(
    transfer_point && transfer_point.is_active === "true" ? true : false
  );
  const [switchLabel, setswitchLabel] = useState("Activate");
  const handleSwitchChange = (checked) => {
    console.log("Swict", checked);
    formik.setFieldValue("is_active", checked ? "true" : "false");
    setswitchLabel(checked ? "Deactivate" : "Activate");

    // console.log('eee', e.target.checked)
  };

  return (
    <div className="w-full">
      <Modal
        width={720}
        className="w-full text-center"
        title={modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.town}
            error={formik.errors.town}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="town"
              id="town"
              label="Select town"
              size="large"
              onChange={(value) => formik.setFieldValue("town", value)}
              value={formik.values.town}
              placeholder="Select town"
              options={towns}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
          >
            <CustomInput
              required={true}
              id="title"
              name="title"
              onChange={formik.handleChange}
              placeholder="Enter transfer point title"
              size="large"
              type="text"
              value={formik.values.title}
              label="Enter transfer point title"
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.abbreviation}
            error={formik.errors.abbreviation}
          >
            <CustomInput
              required={true}
              id="abbreviation"
              name="abbreviation"
              onChange={formik.handleChange}
              placeholder="Enter transfer point abbreviation"
              size="large"
              type="text"
              value={formik.values.abbreviation}
              label="Enter transfer point abbreviation"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.is_active}
            error={formik.errors.is_active}
          >
            <CustomSwitch
              id="is_active"
              checked={formik.values.is_active === "true"}
              onChange={(e) => handleSwitchChange(e)}
              title={switchLabel}
            />
          </CustomFormItem>
          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}

export default PickupPointsFormModal;
